dspark-draft-1.answer:
def reorder_list(products):
    default_threshold = 11
    orders = []
    for product in products:
        stock = product["stock"]
        threshold = product.get("threshold", default_threshold)
        if stock <= threshold:
            quantity = product["target"] - stock
            if quantity > 0:
                orders.append((product["sku"], quantity))
    return orders

